# 5. Issue-prefix disambiguation: issue 6 must not match branch "60-foo".
# The trailing "-" in the startswith match is what prevents the collision.
echo "Test: issue 6 does not match branch 60-foo"
setup
printf '[{"number":10,"headRefName":"60-foo"}]\n' > "$STUB_DIR/pr-list-full.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "6")
assert_eq "issue 6 does not match branch 60-foo → empty" "" "$result"
teardown

# 6. Flake recovery: first pr list call is empty, second returns the PR.
# Models gh pr list flaking (exit 0 + []) on call 1 and returning the real list
# on call 2. The retry-on-empty should produce the PR number.
echo "Test: flake recovery — empty first call, PR on retry → PR number"
setup
printf '[]\n' > "$STUB_DIR/pr-list-full.json"
printf '[{"number":820,"headRefName":"820-x"}]\n' > "$STUB_DIR/pr-list-retry.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "820")
assert_eq "flake recovery → PR number" "820" "$result"
teardown

# 7. Cross-check fallback: pr list yields empty on both attempts, but the
# issue's closedByPullRequestsReferences lists an OPEN PR. This covers the
# case where the branch was renamed away from the <issue>- convention.
echo "Test: cross-check fallback — issue references an OPEN PR → PR number"
setup
printf '[]\n' > "$STUB_DIR/pr-list-full.json"
printf '{"closedByPullRequestsReferences":[{"number":830,"state":"OPEN"}]}\n' \
  > "$STUB_DIR/issue-closing-prs-822.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "822")
assert_eq "cross-check OPEN reference → PR number" "830" "$result"
teardown

# 8. Cross-check ignores non-OPEN references. The script's contract is "open
# PR for issue N or empty"; a MERGED reference must not be reported.
echo "Test: cross-check ignores MERGED reference → empty"
setup
printf '[]\n' > "$STUB_DIR/pr-list-full.json"
printf '{"closedByPullRequestsReferences":[{"number":840,"state":"MERGED"}]}\n' \
  > "$STUB_DIR/issue-closing-prs-822.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "822")
assert_eq "cross-check MERGED reference → empty" "" "$result"
teardown

# 9. Genuine empty: pr list empty on both attempts AND issue references no
# PR. Output stays empty, exit 0 — the "no PR exists" answer.
echo "Test: genuine empty (no PR, no references) → empty"
setup
printf '[]\n' > "$STUB_DIR/pr-list-full.json"
printf '{"closedByPullRequestsReferences":[]}\n' \
  > "$STUB_DIR/issue-closing-prs-822.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "822")
assert_eq "genuine empty → empty" "" "$result"
teardown

# 10. DISPATCH_PR_LIST_FILE supplied without matching branch; cross-check resolves PR.
# The retry (step 1) is skipped when DISPATCH_PR_LIST_FILE is set — the caller owns
# the list. The cross-check (step 2) still runs regardless, using a different gh
# endpoint that the caller cannot pre-supply.
echo "Test: DISPATCH_PR_LIST_FILE no match + cross-check OPEN reference → PR number"
setup
printf '[{"number":850,"headRefName":"999-unrelated"}]\n' > "$STUB_DIR/pr-list-full.json"
printf '{"closedByPullRequestsReferences":[{"number":851,"state":"OPEN"}]}\n' \
  > "$STUB_DIR/issue-closing-prs-822.json"
PR_LIST_F=$(pr_list_tmpfile '[{"number":850,"headRefName":"999-unrelated"}]')
result=$(DISPATCH_PR_LIST_FILE="$PR_LIST_F" \
  "$TMPDIR_TEST/dispatch-find-pr" "822")
assert_eq "DISPATCH_PR_LIST_FILE no prefix match; cross-check finds OPEN PR → PR number" "851" "$result"
# Verify no self-fetch: pr_list_open (number,headRefName) was not called.
if [[ -f "$STUB_DIR/gh-find-pr-calls.log" ]]; then
  call_count=$(wc -l < "$STUB_DIR/gh-find-pr-calls.log")
else
  call_count=0
fi
assert_eq "no self-fetch gh pr list calls when DISPATCH_PR_LIST_FILE set" "0" "$call_count"
teardown

# 11. #1312: No truncation past 30 PRs (proves the --limit 300 fix).
# Before the fix, gh pr list defaulted to --limit 30, so PR 33 of 35 open PRs
# would be silently omitted and dispatch-find-pr would return empty.  With
# --limit 300, the stub case "pr list --state open --limit 300 --json
# number,headRefName" serves all 35 entries from pr-list-full.json, so PR 33
# is found on the first fetch.
echo "Test: #1312 dispatch-find-pr resolves PR 33 of 35 open PRs (no truncation)"
setup
jq -nc '[range(1;36) | {number: ., headRefName: (tostring + "-feature")}]' \
  > "$STUB_DIR/pr-list-full.json"
result=$("$TMPDIR_TEST/dispatch-find-pr" "33")
assert_eq "#1312: dispatch-find-pr resolves PR 33 of 35 open PRs (no truncation)" "33" "$result"
teardown

# 12. #1312: Loud truncation guard fires when result length equals the limit.
# With DISPATCH_PR_LIST_LIMIT=5 the stub returns exactly 5 PRs, which equals
# the limit.  pr_list_open must exit non-zero and write "likely truncated" to
# stderr so the failure is never silent.
echo "Test: #1312 pr_list_open exits non-zero and logs loudly when result length equals the limit"
setup
if err=$(DISPATCH_PR_LIST_LIMIT=5 bash -c \
    'source "'"$TMPDIR_TEST"'/lib.sh" && pr_list_open "number,headRefName"' \
    2>&1 1>/dev/null); then
  rc=0
else
  rc=$?
fi
if [[ "$rc" -ne 0 ]]; then
  PASS=$((PASS + 1))
  TOTAL=$((TOTAL + 1))
  echo "  PASS: #1312: pr_list_open exits non-zero when result length equals the limit"
else
  FAIL=$((FAIL + 1))
  TOTAL=$((TOTAL + 1))
  echo "  FAIL: #1312: pr_list_open exits non-zero when result length equals the limit"
  echo "    expected: non-zero exit"
  echo "    actual:   exit 0"
fi
case "$err" in
  *"likely truncated"*)
    PASS=$((PASS + 1))
    TOTAL=$((TOTAL + 1))
    echo "  PASS: #1312: pr_list_open writes a loud truncation error to stderr"
    ;;
  *)
    FAIL=$((FAIL + 1))
    TOTAL=$((TOTAL + 1))
    echo "  FAIL: #1312: pr_list_open writes a loud truncation error to stderr"
    echo "    expected: stderr containing 'likely truncated'"
    echo "    actual:   '$err'"
    ;;
esac
teardown

# ============================================================================
# dispatch-route tests
# ============================================================================
echo ""
echo "=== dispatch-route ==="

# dispatch-route collapses the worker prelude (worktree cross-check, worktree
# provisioning + origin/main merge, dispatch-ci-ready gate, dispatch-phase) into
# one call and prints exactly one directive. The git stub serves the worktree
# toplevel from worktree-toplevel.txt; the gh stub serves the full-field open-PR
# list from pr-list-full.json and logs each such call to gh-pr-list-calls.log, so
# a test can prove the single DISPATCH_PR_LIST_FILE fetch is reused, not re-issued.
# dispatch-provision-worktree is stubbed in setup() to a no-op exit 0 by default;
# tests 17-20 drive its conflict/failure branches via $STUB_DIR/provision-exit.
route_run() {
  ROUTE_OUT=$("$TMPDIR_TEST/dispatch-route" "$@" 2>/dev/null) && ROUTE_RC=0 || ROUTE_RC=$?
}

# 1. No PR, unplanned → INVOKE /plan-issue (plan phase). dispatch-phase fetches the
# issue's labels (no issue-labels-42.json → no dispatch:planned → plan), and the
# plan arm with no statements config falls through to INVOKE /plan-issue.
echo "Test: no PR, unplanned → INVOKE /plan-issue"
setup
echo '[]' > "$STUB_DIR/pr-list-full.json"
echo "/wt/42-my-feature" > "$STUB_DIR/worktree-toplevel.txt"
echo '{"state":"open","labels":[]}' > "$STUB_DIR/arg-issue-42.json"
route_run 42 /wt/42-my-feature
assert_eq "no PR, unplanned → INVOKE /plan-issue (directive)" "INVOKE /plan-issue" "$ROUTE_OUT"
assert_eq "no PR, unplanned → INVOKE /plan-issue (exit 0)" "0" "$ROUTE_RC"
teardown

# 1a. Provisioning that writes to STDOUT must NOT leak into the directive.
# dispatch-provision-worktree execs dispatch-merge-main, whose `git merge
# origin/main` prints progress ("Updating …/Fast-forward", "Already up to date.")
# to stdout. dispatch-route's contract is "exactly one directive line on stdout",
# and dispatch-launch-worker captures ALL of that stdout and exact-prefix-matches
# it — so leaked merge chatter prepended to the INVOKE line parks the issue as an
# "unrecognized route directive". Override the provision stub to emit multi-line
# stdout and assert dispatch-route still prints ONLY the directive.
echo "Test: provision stdout chatter does not leak into the directive"
setup
echo '[]' > "$STUB_DIR/pr-list-full.json"
echo "/wt/42-my-feature" > "$STUB_DIR/worktree-toplevel.txt"
echo '{"state":"open","labels":[]}' > "$STUB_DIR/arg-issue-42.json"
cat > "$TMPDIR_TEST/dispatch-provision-worktree" <<'STUB'
#!/usr/bin/env bash
printf 'Updating 648157c..ea3a172\nFast-forward\n 2 files changed, 27 insertions(+)\n'
exit 0
STUB
chmod +x "$TMPDIR_TEST/dispatch-provision-worktree"
route_run 42 /wt/42-my-feature
assert_eq "provision stdout chatter → directive is ONLY the INVOKE line" \
  "INVOKE /plan-issue" "$ROUTE_OUT"
assert_eq "provision stdout chatter → exit 0" "0" "$ROUTE_RC"
teardown

# 1b. No PR + dispatch:planned → INVOKE /implement (implement phase). dispatch-phase
# reads dispatch:planned → implement, and the implement arm routes straight to the
# build skill with no relevance review and no parse-job check.
echo "Test: no PR + dispatch:planned → INVOKE /implement"
setup
echo '[]' > "$STUB_DIR/pr-list-full.json"
echo "/wt/42-my-feature" > "$STUB_DIR/worktree-toplevel.txt"
printf '{"state":"open","labels":[{"name":"dispatch:planned"}]}\n' > "$STUB_DIR/arg-issue-42.json"
route_run 42 /wt/42-my-feature
assert_eq "no PR + dispatch:planned → INVOKE /implement (directive)" \
  "INVOKE /implement" "$ROUTE_OUT"
assert_eq "no PR + dispatch:planned → INVOKE /implement (exit 0)" "0" "$ROUTE_RC"
teardown

# 1b-2. No PR + main-qa label → INVOKE /qa-main (#2274). dispatch-route always
# provisions the worktree first (the unconditional dispatch-provision-worktree
# call), then dispatch-phase returns main-qa for the issue; the router maps
# main-qa → INVOKE /qa-main.
echo "Test: no PR + main-qa label → INVOKE /qa-main"
setup
echo '[]' > "$STUB_DIR/pr-list-full.json"
echo "/wt/42-my-feature" > "$STUB_DIR/worktree-toplevel.txt"
printf '{"state":"open","labels":[{"name":"main-qa"}]}\n' > "$STUB_DIR/arg-issue-42.json"
route_run 42 /wt/42-my-feature
assert_eq "no PR + main-qa → INVOKE /qa-main (directive)" "INVOKE /qa-main" "$ROUTE_OUT"
assert_eq "no PR + main-qa → INVOKE /qa-main (exit 0)" "0" "$ROUTE_RC"
teardown

# 1c. Closed issue → STOP closed (#1845). The router's closed-issue guard fires
# AFTER the worktree cross-check and BEFORE provisioning: it fetches the issue
# state once and short-circuits a closed issue so its lingering worktree is never
# routed to a phase skill. issue-state-43.json marks #43 CLOSED. On the PRE-FIX
# code (no guard) this routed to INVOKE /plan-issue (no PR, unplanned), so the
# assertion genuinely guards the new behavior.
echo "Test: closed issue → STOP closed"
setup
echo '[]' > "$STUB_DIR/pr-list-full.json"
echo "/wt/43-closed-feature" > "$STUB_DIR/worktree-toplevel.txt"
echo '{"state":"closed"}' > "$STUB_DIR/arg-issue-43.json"
route_run 43 /wt/43-closed-feature
assert_eq "closed issue → STOP closed (directive)" "STOP closed" "$ROUTE_OUT"
assert_eq "closed issue → STOP closed (exit 0)" "0" "$ROUTE_RC"
teardown

# 1d. Criterion #4 (#1845): a closed issue must NEVER be office-hours-parked. The
# route-level test above cannot prove this — dispatch-launch-worker's case arm is
# what routes STOP closed to the no-park benign-races handler (release_and_tick,
# no dispatch-apply-office-hours). Driving the launcher end-to-end is out of scope
# for this harness, so assert at the source that STOP closed is in the no-park arm.
echo "Test: dispatch-launch-worker lists STOP closed in the no-park benign arm"
TOTAL=$((TOTAL + 1))
# Match the no-park benign-races case arm loosely: a single case-arm line that
# bundles "STOP closed" with at least one other benign STOP alternative and ends
# the pattern list with `)`. This tolerates future reordering or added
# alternatives (e.g. `| "STOP pr-list-failed")`) without a false FAIL, while the
# `\|` between alternatives still distinguishes this shared arm from the lone
# `*)` park arm.
if grep -Eq '"STOP [a-z-]+" \|.*"STOP closed".*\)' \
   "$SCRIPT_DIR/dispatch-launch-worker"; then
  PASS=$((PASS + 1)); echo "  PASS: STOP closed is in the launcher's no-park benign-races arm"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: STOP closed is in the launcher's no-park benign-races arm"
fi

