printf 'worktree /repo\nHEAD abc123\n\n' > "$STUB_DIR/worktree-list.txt"
result=$("$TMPDIR_TEST/dispatch-select-target")
assert_eq "green draft PR selected by PR queue as qa" "pr 10 55-feature qa" "$result"
