[[ "$rc" -ne 0 ]] && rc_nonzero=yes || rc_nonzero=no
assert_eq "invalid duration → exits non-zero" "yes" "$rc_nonzero"
teardown

# OH1. The PR-phase office-hours skip is issue-anchored (issue #909): see the
