TOTAL=$((TOTAL + 1))
if printf '%s' "$err" | grep -q 'inspect tmp/dispatch-launch'; then
  FAIL=$((FAIL + 1)); echo "  FAIL: rl-sweep-redundant: benign reclaim stays silent (no launch-log diagnostic)"
  echo "    stderr: $err"
