cat > "$TMPDIR_TEST/bin/systemd-run" <<STUB
#!/usr/bin/env bash
echo "\$*" >> "$TMPDIR_TEST/systemd-log"
count=\$(wc -l < "$TMPDIR_TEST/systemd-log")
if [[ "\$count" -gt 1 ]]; then
  echo "Unit dispatch-reseed-20000.timer already exists." >&2
  exit 1
fi
STUB
chmod +x "$TMPDIR_TEST/bin/systemd-run"

