  PASS=$((PASS + 1)); echo "  PASS: second call stderr notes already-scheduled"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: second call stderr notes already-scheduled"
  echo "    stderr2: $err2"
fi
sr_teardown

