assert_eq "#1136 5h resets far-future → timer at weekly reset" \
  "scheduled dispatch-reseed-$weekly_reset at $weekly_reset" "$out"
log=$(cat "$TMPDIR_TEST/systemd-log" 2>/dev/null || true)
TOTAL=$((TOTAL + 1))
