else
  FAIL=$((FAIL + 1)); echo "  FAIL: #1136 5h resets far-future → expected timer at weekly $weekly_reset + diagnostic"
  echo "    log: $log"
  echo "    stderr: $(cat "$TMPDIR_TEST/stderr")"
fi
sr_teardown

