fi
echo "\$*" >> "$TMPDIR_TEST/gh-edit-log"
exit 0
STUB
  chmod +x "$TMPDIR_TEST/bin/fake-gh"
  export DISPATCH_ATTEMPT_COUNT_GH_CMD="$TMPDIR_TEST/bin/fake-gh"
}

