  >/dev/null 2>&1 || rc=$?
TOTAL=$((TOTAL + 1))
if [[ "$rc" -ne 0 ]]; then
  PASS=$((PASS + 1))
  echo "  PASS: reader exits non-zero for an absent issue"
else
  FAIL=$((FAIL + 1))
  echo "  FAIL: reader exits non-zero for an absent issue"
  echo "    expected: non-zero, actual: 0"
fi
