   && "$log" == *"--property=OnFailure=dispatch-tick-recover.service"* \
   && "$log" == *"--property=KillMode=process"* \
   && "$log" == *"$TMPDIR_TEST/main/.claude/skills/dispatch-propagate/scripts/dispatch-tick 979"* ]]; then
