[[ -f "$STUB_DIR/gh-issue-create-rest-calls.log" ]] \
  && creates_before=$(wc -l < "$STUB_DIR/gh-issue-create-rest-calls.log")
# Run 2: the open-issue guard fires — skipped, no second create.
