  PASS=$((PASS + 1)); echo "  PASS: open-hit made no issue create call"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: open-hit made no issue create call"
  echo "    gh-issue-create-rest-calls.log: $(cat "$STUB_DIR/gh-issue-create-rest-calls.log")"
fi
