apply_log=$(cat "$STUB_DIR/apply-office-hours.log" 2>/dev/null || true)
apply_issue=$(printf '%s' "$apply_log" | awk '{print $1}')
apply_reason=$(printf '%s' "$apply_log" | cut -d' ' -f2-)
TOTAL=$((TOTAL + 1))
