IN='{"findings":[{"id":"r1","bucket":"Required"},{"id":"r2","bucket":"Required"},{"id":"r3","bucket":"Required"},{"id":"r4","bucket":"Required"},{"id":"i1","bucket":"Informational"}],"votes":{"r1":["refuted","upheld"],"r2":["refuted","refuted"],"r3":["upheld","upheld"]}}'
