# ============================================================================
# ensure_daemon_service: durable daemon service install + attach paths (#1197)
# ============================================================================
echo ""
echo "=== ensure_daemon_service durable supervisor service ==="
# A recording systemctl stub: appends its argv to $STUB_LOG and returns exit
# codes driven by env flags, so `is-active` can be made to report active /
# inactive and `enable` can be made to fail (simulating no systemd --user).
eds_tmp=$(mktemp -d)
mkdir -p "$eds_tmp/bin"
cat > "$eds_tmp/bin/systemctl" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$STUB_LOG"
for a in "$@"; do
  case "$a" in
    is-active) exit "${STUB_IS_ACTIVE_RC:-0}" ;;
    enable) exit "${STUB_ENABLE_RC:-0}" ;;
    daemon-reload) exit "${STUB_RELOAD_RC:-0}" ;;
  esac
done
exit 0
STUB
chmod +x "$eds_tmp/bin/systemctl"
# A dummy claude binary path — the unit bakes it into ExecStart; it is never run.
eds_claude="$eds_tmp/bin/claude"
cat > "$eds_claude" <<'STUB'
#!/usr/bin/env bash
exit 0
STUB
chmod +x "$eds_claude"
eds_unit_dir="$eds_tmp/systemd-user"
eds_unit="$eds_unit_dir/dispatch-claude-daemon.service"
eds_log="$eds_tmp/systemctl.log"

# --- 1. Idempotent install (cold path) --------------------------------------
: > "$eds_log"
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_unit_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=0 STUB_ENABLE_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
); then
  if [ -f "$eds_unit" ]; then
    TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path wrote the unit file"
    grep -q '^Type=simple$' "$eds_unit" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: unit has Type=simple"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: unit missing Type=simple"; }
    grep -q '^Restart=always$' "$eds_unit" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: unit has Restart=always"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: unit missing Restart=always"; }
    grep -q '^WantedBy=default.target$' "$eds_unit" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: unit has WantedBy=default.target"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: unit missing WantedBy=default.target"; }
    eds_exec=$(grep '^ExecStart=' "$eds_unit")
    assert_eq "ExecStart= is the claude path + daemon run" \
      "ExecStart=\"$eds_claude\" daemon run" "$eds_exec"
    TOTAL=$((TOTAL + 1))
    if [[ "$eds_exec" != *"--origin service"* ]]; then
      PASS=$((PASS + 1)); echo "  PASS: ExecStart is not --origin service"
    else
      FAIL=$((FAIL + 1)); echo "  FAIL: ExecStart uses --origin service: $eds_exec"
    fi
  else
    TOTAL=$((TOTAL + 6)); FAIL=$((FAIL + 6))
    echo "  FAIL: cold path did not write the unit file"
  fi
  grep -q 'daemon-reload' "$eds_log" \
    && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path ran daemon-reload"; } \
    || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: cold path did not run daemon-reload"; }
  grep -q 'enable --now dispatch-claude-daemon.service' "$eds_log" \
    && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path ran enable --now"; } \
    || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: cold path did not run enable --now"; }
else
  TOTAL=$((TOTAL + 8)); FAIL=$((FAIL + 8))
  echo "  FAIL: ensure_daemon_service (cold path) returned non-zero"
fi

# --- 2. Attach-to-existing-daemon path (steady-state no-op) ------------------
# Unit already written (from test 1) and is-active reports active → no-op: no
# rewrite (no daemon-reload) and no enable.
: > "$eds_log"
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_unit_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=0 STUB_ENABLE_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
); then
  TOTAL=$((TOTAL + 1))
  if ! grep -q 'enable' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: attach path did not re-run enable"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: attach path re-ran enable"
  fi
  TOTAL=$((TOTAL + 1))
  if ! grep -q 'daemon-reload' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: attach path did not rewrite the unit (no daemon-reload)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: attach path rewrote the unit (daemon-reload ran)"
  fi
else
  TOTAL=$((TOTAL + 2)); FAIL=$((FAIL + 2))
  echo "  FAIL: ensure_daemon_service (attach path) returned non-zero"
fi

# --- 3. Inactive self-heal --------------------------------------------------
# Content matches but is-active reports inactive → the write branch is skipped
# (the unit is NOT rewritten — same inode), yet daemon-reload AND enable --now
# both run on the slow path to revive it. Running daemon-reload even on the
# unchanged-content slow path is the stuck-state fix (see test 3b): a reload
# that failed on a prior call left the unit on disk but unloaded, and the
# content compare would otherwise skip it forever. So "not rewritten" is
# asserted by inode stability, not by the absence of daemon-reload.
: > "$eds_log"
eds_inode_before=$(stat -c '%i' "$eds_unit")
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_unit_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=3 STUB_ENABLE_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
); then
  TOTAL=$((TOTAL + 1))
  if grep -q 'enable --now dispatch-claude-daemon.service' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: inactive self-heal ran enable --now"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: inactive self-heal did not run enable --now"
  fi
  TOTAL=$((TOTAL + 1))
  if grep -q 'daemon-reload' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: inactive self-heal ran daemon-reload (stuck-state retry)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: inactive self-heal skipped daemon-reload"
  fi
  TOTAL=$((TOTAL + 1))
  if [ "$(stat -c '%i' "$eds_unit")" = "$eds_inode_before" ]; then
    PASS=$((PASS + 1)); echo "  PASS: inactive self-heal did not rewrite the unchanged unit (inode stable)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: inactive self-heal rewrote the unchanged unit (inode changed)"
  fi
else
  TOTAL=$((TOTAL + 3)); FAIL=$((FAIL + 3))
  echo "  FAIL: ensure_daemon_service (inactive self-heal) returned non-zero"
fi

# --- 3b. daemon-reload failure must not wedge the unit -----------------------
# Regression guard for the stuck-state bug: the first call writes the unit to
# disk (mv succeeds) but daemon-reload fails (STUB_RELOAD_RC=1), so the call
# returns non-zero. The unit is now on disk byte-for-byte, but systemd never
# loaded it. A second call (with daemon-reload healthy) MUST retry daemon-reload
# and reach enable --now — otherwise the content-compare short-circuit skips the
# write branch forever, leaving an unloaded unit that can never activate.
eds_reload_dir="$eds_tmp/reload-fail"
eds_reload_unit="$eds_reload_dir/dispatch-claude-daemon.service"
# First call: daemon-reload fails → non-zero return, but unit lands on disk.
: > "$eds_log"
eds_reload_rc1=0
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_reload_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=0 STUB_ENABLE_RC=0 STUB_RELOAD_RC=1
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
) 2>/dev/null; then
  eds_reload_rc1=0
else
  eds_reload_rc1=$?
fi
assert_eq "reload-fail: first call (daemon-reload fails) → non-zero return" "1" "$eds_reload_rc1"
TOTAL=$((TOTAL + 1))
if [ -f "$eds_reload_unit" ]; then
  PASS=$((PASS + 1)); echo "  PASS: reload-fail first call left the unit on disk"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: reload-fail first call did not write the unit"
fi
TOTAL=$((TOTAL + 1))
if ! grep -q 'enable' "$eds_log"; then
  PASS=$((PASS + 1)); echo "  PASS: reload-fail first call did not reach enable"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: reload-fail first call reached enable despite reload failure"
fi
# Second call: daemon-reload healthy. is-active reports inactive (RC=3) so the
# steady-state short-circuit cannot mask a missing retry. The call MUST retry
# daemon-reload and reach enable --now, and must succeed.
: > "$eds_log"
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_reload_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=3 STUB_ENABLE_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
); then
  TOTAL=$((TOTAL + 1))
  if grep -q 'daemon-reload' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: reload-fail recovery retried daemon-reload"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: reload-fail recovery did not retry daemon-reload (unit wedged)"
  fi
  TOTAL=$((TOTAL + 1))
  if grep -q 'enable --now dispatch-claude-daemon.service' "$eds_log"; then
    PASS=$((PASS + 1)); echo "  PASS: reload-fail recovery reached enable --now"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: reload-fail recovery did not reach enable --now"
  fi
else
  TOTAL=$((TOTAL + 2)); FAIL=$((FAIL + 2))
  echo "  FAIL: ensure_daemon_service (reload-fail recovery) returned non-zero"
fi

# --- 4. Degrade safely ------------------------------------------------------
# 4a. enable fails (simulating no systemd --user) → returns non-zero, does not
# abort the test shell.
: > "$eds_log"
eds_degrade_dir="$eds_tmp/degrade"
# Guarded with `if` so the script's `set -e` does not abort on the intended
# non-zero return from the degrade path.
eds_rc=0
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_degrade_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=0 STUB_ENABLE_RC=1 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
) 2>/dev/null; then
  eds_rc=0
else
  eds_rc=$?
fi
assert_eq "degrade: enable failure → non-zero return" "1" "$eds_rc"
echo "  (test shell survived the degrade path)"

# 4b. claude binary not found → non-zero return. Empty CLAUDE_CMD falls back to
# `command -v claude`, so PATH must also lack claude for "not found" to hold.
eds_rc2=0
(
  source "$SCRIPT_DIR/lib.sh"
  export DISPATCH_DAEMON_UNIT_DIR="$eds_tmp/no-claude"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD=""
  export STUB_LOG="$eds_log"
  export PATH="/nonexistent"
  ensure_daemon_service
) 2>/dev/null || eds_rc2=$?
TOTAL=$((TOTAL + 1))
if [[ "$eds_rc2" -ne 0 ]]; then
  PASS=$((PASS + 1)); echo "  PASS: empty claude path → non-zero return"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: empty claude path returned zero"
fi

# --- 5. PATH backslash is stripped from daemon Environment= (#1212) ----------
echo ""
echo "=== ensure_daemon_service strips backslash from Environment= PATH ==="
eds_path_strip_dir="$eds_tmp/path-strip-systemd-user"
eds_path_strip_rc=0
if (
  export DISPATCH_DAEMON_UNIT_DIR="$eds_path_strip_dir"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_claude"
  export STUB_LOG="$eds_log"
  export STUB_IS_ACTIVE_RC=0 STUB_ENABLE_RC=0 STUB_RELOAD_RC=0
  export PATH="/usr/bin:/mnt/c/win\\dows:$PATH"
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
); then
  eds_path_strip_unit="$eds_path_strip_dir/dispatch-claude-daemon.service"
  if eds_path_env_line=$(grep '^Environment=' "$eds_path_strip_unit" 2>/dev/null); then
    TOTAL=$((TOTAL + 1))
    if [[ "$eds_path_env_line" != *'\'* ]]; then
      PASS=$((PASS + 1)); echo "  PASS: daemon Environment= PATH has no backslash (stripped)"
    else
      FAIL=$((FAIL + 1)); echo "  FAIL: daemon Environment= PATH still contains a backslash: $eds_path_env_line"
    fi
  else
    TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1))
    echo "  FAIL: daemon unit missing or lacks Environment= line: $eds_path_strip_unit"
  fi
else
  TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1))
  echo "  FAIL: ensure_daemon_service returned non-zero (path-strip test)"
fi

# --- 6. ensure_daemon_service rejects a claude path with a backslash (#1212) -
echo ""
echo "=== ensure_daemon_service rejects a claude path with a backslash ==="
eds_reject_rc=0
(
  export DISPATCH_DAEMON_UNIT_DIR="$eds_tmp/reject-systemd-user"
  export DISPATCH_DAEMON_SYSTEMCTL_CMD="$eds_tmp/bin/systemctl"
  export DISPATCH_DAEMON_CLAUDE_CMD="$eds_tmp/bin/cla\\ude"
  export STUB_LOG="$eds_log"
  source "$SCRIPT_DIR/lib.sh"
  ensure_daemon_service
) 2>/dev/null || eds_reject_rc=$?
TOTAL=$((TOTAL + 1))
if [[ "$eds_reject_rc" -ne 0 ]]; then
  PASS=$((PASS + 1)); echo "  PASS: ensure_daemon_service returned non-zero for a claude path with a backslash"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: ensure_daemon_service returned zero for a claude path with a backslash"
fi
TOTAL=$((TOTAL + 1))
if [[ ! -e "$eds_tmp/reject-systemd-user/dispatch-claude-daemon.service" ]]; then
  PASS=$((PASS + 1)); echo "  PASS: no daemon unit written for a claude path with a backslash"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: daemon unit was written despite claude path containing a backslash"
fi

rm -rf "$eds_tmp"

# ============================================================================
# ensure_heartbeat_units: correct unit content + idempotency (#2022)
# ============================================================================
#
# Mirrors the ensure_daemon_service recording-stub block above. A recording
# systemctl stub appends its argv to $ehu_log and returns exit codes driven by
# STUB_IS_ACTIVE_RC / STUB_ENABLE_RC / STUB_RELOAD_RC env flags.  Cold path
# (unit files absent): writes both unit files, runs daemon-reload and enable
# --now.  Hot path (both units byte-identical AND timer active): returns early
# without daemon-reload or enable --now.
echo ""
echo "=== ensure_heartbeat_units: unit content + idempotency (#2022) ==="
ehu_tmp=$(mktemp -d)
mkdir -p "$ehu_tmp/bin" "$ehu_tmp/main-worktree"
cat > "$ehu_tmp/bin/systemctl" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$STUB_LOG"
for a in "$@"; do
  case "$a" in
    show) printf '%s\n' "${STUB_SUBSTATE-dead}"; exit 0 ;;
    is-active) exit "${STUB_IS_ACTIVE_RC:-0}" ;;
    enable)    exit "${STUB_ENABLE_RC:-0}" ;;
    restart)   exit "${STUB_RESTART_RC:-0}" ;;
    daemon-reload) exit "${STUB_RELOAD_RC:-0}" ;;
  esac
done
exit 0
STUB
chmod +x "$ehu_tmp/bin/systemctl"
ehu_unit_dir="$ehu_tmp/systemd-user"
ehu_svc="$ehu_unit_dir/dispatch-heartbeat.service"
ehu_tmr="$ehu_unit_dir/dispatch-heartbeat.timer"
ehu_log="$ehu_tmp/systemctl.log"

# --- 1. Cold path: writes both unit files, runs daemon-reload + enable --now -
: > "$ehu_log"
if (
  export DISPATCH_HEARTBEAT_UNIT_DIR="$ehu_unit_dir"
  export DISPATCH_HEARTBEAT_SYSTEMCTL_CMD="$ehu_tmp/bin/systemctl"
  export STUB_LOG="$ehu_log"
  export STUB_SUBSTATE=dead STUB_ENABLE_RC=0 STUB_RESTART_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_heartbeat_units "$ehu_tmp/main-worktree"
); then
  if [ -f "$ehu_svc" ]; then
    TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path wrote dispatch-heartbeat.service"
    grep -qF '/dispatch-tick' "$ehu_svc" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: service ExecStart= references dispatch-tick"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: service ExecStart= missing dispatch-tick"; }
    grep -q '^KillMode=process$' "$ehu_svc" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: service has KillMode=process"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: service missing KillMode=process"; }
    grep -q '^OnFailure=dispatch-tick-recover.service$' "$ehu_svc" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: service has OnFailure=dispatch-tick-recover.service"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: service missing OnFailure=dispatch-tick-recover.service"; }
  else
    TOTAL=$((TOTAL + 4)); FAIL=$((FAIL + 4))
    echo "  FAIL: cold path did not write dispatch-heartbeat.service"
  fi
  if [ -f "$ehu_tmr" ]; then
    TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path wrote dispatch-heartbeat.timer"
    grep -q '^OnCalendar=\*:0/15$' "$ehu_tmr" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: timer has OnCalendar=*:0/15"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: timer missing OnCalendar=*:0/15"; }
    grep -q '^OnBootSec=2min$' "$ehu_tmr" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: timer has OnBootSec=2min"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: timer missing OnBootSec=2min"; }
    grep -q '^Persistent=true$' "$ehu_tmr" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: timer has Persistent=true"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: timer missing Persistent=true"; }
    grep -q '^RandomizedDelaySec=30$' "$ehu_tmr" \
      && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: timer has RandomizedDelaySec=30"; } \
      || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: timer missing RandomizedDelaySec=30"; }
  else
    TOTAL=$((TOTAL + 5)); FAIL=$((FAIL + 5))
    echo "  FAIL: cold path did not write dispatch-heartbeat.timer"
  fi
  grep -q 'daemon-reload' "$ehu_log" \
    && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path ran daemon-reload"; } \
    || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: cold path did not run daemon-reload"; }
  grep -q 'enable dispatch-heartbeat.timer' "$ehu_log" \
    && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path ran enable dispatch-heartbeat.timer"; } \
    || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: cold path did not run enable dispatch-heartbeat.timer"; }
  grep -q 'restart dispatch-heartbeat.timer' "$ehu_log" \
    && { TOTAL=$((TOTAL + 1)); PASS=$((PASS + 1)); echo "  PASS: cold path ran restart dispatch-heartbeat.timer"; } \
    || { TOTAL=$((TOTAL + 1)); FAIL=$((FAIL + 1)); echo "  FAIL: cold path did not run restart dispatch-heartbeat.timer"; }
else
  TOTAL=$((TOTAL + 12)); FAIL=$((FAIL + 12))
  echo "  FAIL: ensure_heartbeat_units (cold path) returned non-zero"
fi

# --- 2. Hot path: both units byte-identical + timer armed → no-op -------------
# The hot-path short-circuit checks SubState (STUB_SUBSTATE=waiting → armed); it
# returns early and must not run daemon-reload, enable, or restart.
: > "$ehu_log"
if (
  export DISPATCH_HEARTBEAT_UNIT_DIR="$ehu_unit_dir"
  export DISPATCH_HEARTBEAT_SYSTEMCTL_CMD="$ehu_tmp/bin/systemctl"
  export STUB_LOG="$ehu_log"
  export STUB_SUBSTATE=waiting STUB_ENABLE_RC=0 STUB_RESTART_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_heartbeat_units "$ehu_tmp/main-worktree"
); then
  TOTAL=$((TOTAL + 1))
  if ! grep -q 'daemon-reload' "$ehu_log"; then
    PASS=$((PASS + 1)); echo "  PASS: hot path did not rewrite units (no daemon-reload)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: hot path ran daemon-reload (spurious rewrite)"
  fi
  TOTAL=$((TOTAL + 1))
  if ! grep -q 'enable' "$ehu_log"; then
    PASS=$((PASS + 1)); echo "  PASS: hot path did not re-run enable"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: hot path re-ran enable"
  fi
  TOTAL=$((TOTAL + 1))
  if ! grep -q 'restart' "$ehu_log"; then
    PASS=$((PASS + 1)); echo "  PASS: hot path did not re-run restart"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: hot path re-ran restart"
  fi
else
  TOTAL=$((TOTAL + 3)); FAIL=$((FAIL + 3))
  echo "  FAIL: ensure_heartbeat_units (hot path) returned non-zero"
fi

# --- 2b. Elapsed strand: units match but SubState=elapsed → repair (#2375) -----
# The #2375 stranded state: units are byte-identical on disk (installed by the
# cold path above, still present), but the timer is active (elapsed) — no future
# fire. is-active would read 0 (healthy), but heartbeat_timer_is_armed requires
# SubState=waiting, so this must fall through to the repair path and re-arm:
# daemon-reload + restart fire.
: > "$ehu_log"
if (
  export DISPATCH_HEARTBEAT_UNIT_DIR="$ehu_unit_dir"
  export DISPATCH_HEARTBEAT_SYSTEMCTL_CMD="$ehu_tmp/bin/systemctl"
  export STUB_LOG="$ehu_log"
  export STUB_SUBSTATE=elapsed STUB_ENABLE_RC=0 STUB_RESTART_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_heartbeat_units "$ehu_tmp/main-worktree"
); then
  TOTAL=$((TOTAL + 1))
  if grep -q 'daemon-reload' "$ehu_log"; then
    PASS=$((PASS + 1)); echo "  PASS: elapsed timer fell through to repair (daemon-reload)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: elapsed timer short-circuited (no daemon-reload)"
  fi
  TOTAL=$((TOTAL + 1))
  if grep -q 'restart dispatch-heartbeat.timer' "$ehu_log"; then
    PASS=$((PASS + 1)); echo "  PASS: elapsed timer is re-armed (#2375) (restart fired)"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL: elapsed timer was not re-armed (no restart)"
  fi
else
  TOTAL=$((TOTAL + 2)); FAIL=$((FAIL + 2))
  echo "  FAIL: ensure_heartbeat_units (elapsed strand) returned non-zero"
fi

# --- 2c. Restart failure → non-zero return + WARNING (RV-002, #2388) ----------
# enable succeeds but `systemctl restart` fails (STUB_RESTART_RC=1). SubState=dead
# forces fall-through past the hot-path early-return so the restart step is reached;
# the install/re-arm path must surface a non-zero return and a WARNING to stderr
# (lib.sh:2868-2870).
: > "$ehu_log"
ehu_restart_stderr="$ehu_tmp/restart-fail.stderr"
ehu_restart_rc=0
(
  export DISPATCH_HEARTBEAT_UNIT_DIR="$ehu_unit_dir"
  export DISPATCH_HEARTBEAT_SYSTEMCTL_CMD="$ehu_tmp/bin/systemctl"
  export STUB_LOG="$ehu_log"
  export STUB_SUBSTATE=dead STUB_ENABLE_RC=0 STUB_RESTART_RC=1 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_heartbeat_units "$ehu_tmp/main-worktree"
) 2>"$ehu_restart_stderr" || ehu_restart_rc=$?
assert_eq "restart failure → non-zero return" "1" "$ehu_restart_rc"
TOTAL=$((TOTAL + 1))
if grep -q 'WARNING: ensure_heartbeat_units: systemctl --user restart dispatch-heartbeat.timer failed' "$ehu_restart_stderr"; then
  PASS=$((PASS + 1)); echo "  PASS: restart failure emitted WARNING to stderr"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: restart failure did not emit expected WARNING to stderr"
fi

# --- 2d. Elapsed strand + enable fails → repair path returns non-zero, WARNs --
# Parity with the cold-path degrade case (block 4a in the ensure_daemon_service
# suite): on the elapsed/repair path, when `systemctl --user enable` fails the
# function must return non-zero AND emit its WARNING to stderr (lib.sh:2864-2867,
# RV-003 from PR #2382). Reuses the units the cold path installed in
# $ehu_unit_dir; redirects stderr to a file so the WARNING can be asserted.
: > "$ehu_log"
ehu_err="$ehu_tmp/enable-fail-stderr"
ehu_rc=0
if (
  export DISPATCH_HEARTBEAT_UNIT_DIR="$ehu_unit_dir"
  export DISPATCH_HEARTBEAT_SYSTEMCTL_CMD="$ehu_tmp/bin/systemctl"
  export STUB_LOG="$ehu_log"
  export STUB_SUBSTATE=elapsed STUB_ENABLE_RC=1 STUB_RESTART_RC=0 STUB_RELOAD_RC=0
  source "$SCRIPT_DIR/lib.sh"
  ensure_heartbeat_units "$ehu_tmp/main-worktree"
) 2>"$ehu_err"; then
  ehu_rc=0
else
  ehu_rc=$?
fi
assert_eq "elapsed+enable-fail: ensure_heartbeat_units returns non-zero" "1" "$ehu_rc"
assert_eq "elapsed+enable-fail: WARNING on stderr" "present" \
  "$(grep -q 'WARNING: ensure_heartbeat_units: systemctl --user enable dispatch-heartbeat.timer failed' "$ehu_err" \
     && echo present || echo absent)"

# --- 3. cleanup_stale_heartbeat_units: path-change disable (#2056) ------------
# Called DIRECTLY (not via ensure_heartbeat_units): the "paths match" case would
# otherwise hit the hot-path early-return before reaching the cleanup call.
mkdir -p "$ehu_unit_dir"

# 3a. AC1 — installed WorkingDirectory differs from current → disable fires.
: > "$ehu_log"
printf '%s\n' '[Service]' 'WorkingDirectory=/old/path' > "$ehu_svc"
(
  export STUB_LOG="$ehu_log"
  source "$SCRIPT_DIR/lib.sh"
  cleanup_stale_heartbeat_units "$ehu_svc" "$ehu_tmp/main-worktree" "$ehu_tmp/bin/systemctl"
)
TOTAL=$((TOTAL + 1))
if grep -q 'disable --now dispatch-heartbeat.timer dispatch-heartbeat.service' "$ehu_log"; then
  PASS=$((PASS + 1)); echo "  PASS: cleanup_stale_heartbeat_units disabled stale units on path change"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: cleanup_stale_heartbeat_units did not disable on path change"
fi

# 3b. AC2 — installed WorkingDirectory matches current → no disable.
: > "$ehu_log"
printf '%s\n' '[Service]' "WorkingDirectory=$ehu_tmp/main-worktree" > "$ehu_svc"
(
  export STUB_LOG="$ehu_log"
  source "$SCRIPT_DIR/lib.sh"
  cleanup_stale_heartbeat_units "$ehu_svc" "$ehu_tmp/main-worktree" "$ehu_tmp/bin/systemctl"
)
TOTAL=$((TOTAL + 1))
if ! grep -q 'disable' "$ehu_log"; then
  PASS=$((PASS + 1)); echo "  PASS: cleanup_stale_heartbeat_units did not disable when path matches"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: cleanup_stale_heartbeat_units disabled despite matching path"
fi

# 3c. AC3 — no prior service unit → no-op (returns 0, no disable).
: > "$ehu_log"
ehu_missing_svc="$ehu_unit_dir/does-not-exist.service"
ehu_cleanup_rc=0
(
  export STUB_LOG="$ehu_log"
  source "$SCRIPT_DIR/lib.sh"
  cleanup_stale_heartbeat_units "$ehu_missing_svc" "$ehu_tmp/main-worktree" "$ehu_tmp/bin/systemctl"
) || ehu_cleanup_rc=$?
assert_eq "cleanup_stale_heartbeat_units: missing unit → returns 0" "0" "$ehu_cleanup_rc"
# Counts the inline grep check below; the assert_eq above counts itself.
TOTAL=$((TOTAL + 1))
if ! grep -q 'disable' "$ehu_log"; then
  PASS=$((PASS + 1)); echo "  PASS: cleanup_stale_heartbeat_units no-op when no prior units"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: cleanup_stale_heartbeat_units ran disable with no prior units"
fi

# 3d. AC4 (#2191) — [Service] section present but no WorkingDirectory= line →
# early return at lib.sh:1810 ([ -n "$installed_workdir" ] || return 0): no
# disable, returns 0.
: > "$ehu_log"
printf '%s\n' '[Service]' > "$ehu_svc"
ehu_cleanup_rc=0
(
  export STUB_LOG="$ehu_log"
  source "$SCRIPT_DIR/lib.sh"
  cleanup_stale_heartbeat_units "$ehu_svc" "$ehu_tmp/main-worktree" "$ehu_tmp/bin/systemctl"
) || ehu_cleanup_rc=$?
assert_eq "cleanup_stale_heartbeat_units: no WorkingDirectory= → returns 0" "0" "$ehu_cleanup_rc"
# Counts the inline grep check below; the assert_eq above counts itself.
TOTAL=$((TOTAL + 1))
if ! grep -q 'disable' "$ehu_log"; then
  PASS=$((PASS + 1)); echo "  PASS: cleanup_stale_heartbeat_units no-op when WorkingDirectory= absent"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: cleanup_stale_heartbeat_units ran disable with no WorkingDirectory="
fi

rm -rf "$ehu_tmp"

# ============================================================================
# dispatch-write-plan / dispatch-read-plan tests
# ============================================================================
echo ""
echo "=== dispatch-write-plan / dispatch-read-plan ==="

# These two scripts exercise a stateful gh comment store, so this block builds
# its own fake `gh` (a generic `gh api` emulator over a JSON file) rather than
# reusing the shared fixture stub. The fake honors: GET .../issues/<N>/comments
# (returns the store array), GET .../issues/comments/<id> (returns one comment),
# POST .../issues/<N>/comments (append), PATCH .../issues/comments/<id> (replace
# body). It pipes the response through the REAL `jq` when --jq is given.
wp_root=$(mktemp -d)
mkdir -p "$wp_root/bin"
WP_STORE="$wp_root/store.json"
WP_COUNTER="$wp_root/counter"
echo '[]' > "$WP_STORE"
echo '0' > "$WP_COUNTER"
cat > "$wp_root/bin/gh" <<WPGH
#!/usr/bin/env bash
# Generic gh api emulator over a JSON comment store. Only the surface the two
# plan scripts use is implemented.
set -uo pipefail
STORE="$WP_STORE"
COUNTER="$WP_COUNTER"
WPGH
cat >> "$wp_root/bin/gh" <<'WPGH'
method="GET"
endpoint=""
jqfilter=""
bodyfile=""
# First arg is the gh subcommand group; we only support "api".
if [[ "${1:-}" != "api" ]]; then
  echo "fake-gh: unsupported subcommand: ${1:-}" >&2; exit 1
fi
shift
while [[ $# -gt 0 ]]; do
  case "$1" in
    --method) method="$2"; shift 2 ;;
    --paginate) shift ;;
    --jq) jqfilter="$2"; shift 2 ;;
    --field)
      # Expect body=@<file>
      val="$2"; shift 2
      case "$val" in
        body=@*) bodyfile="${val#body=@}" ;;
        *) ;; # ignore other fields
      esac
      ;;
    -f) # alternate field form, ignore unless body=@
      val="$2"; shift 2
      case "$val" in
        body=@*) bodyfile="${val#body=@}" ;;
        *) ;;
      esac
      ;;
    -*) shift ;;            # ignore unknown flags
    *)
      if [[ -z "$endpoint" ]]; then endpoint="$1"; fi
      shift
      ;;
  esac
done

emit() {
  # $1 = JSON response. Pipe through real jq if a filter was given.
  if [[ -n "$jqfilter" ]]; then
    printf '%s' "$1" | jq -r "$jqfilter"
  else
    printf '%s' "$1"
  fi
}

# Strip a trailing/leading nothing; match endpoint shapes.
if [[ "$method" == "GET" && "$endpoint" == *"/comments" && "$endpoint" != *"/issues/comments/"* ]]; then
  # GET .../issues/<N>/comments  → the whole store array
  emit "$(cat "$STORE")"
  exit 0
fi
if [[ "$method" == "GET" && "$endpoint" == *"/issues/comments/"* ]]; then
  cid="${endpoint##*/issues/comments/}"
  obj=$(jq -c --argjson id "$cid" '.[] | select(.id == $id)' "$STORE")
  if [[ -z "$obj" ]]; then
    echo "fake-gh: comment $cid not found" >&2; exit 1
  fi
  emit "$obj"
  exit 0
fi
if [[ "$method" == "POST" && "$endpoint" == *"/comments" ]]; then
  next=$(( $(cat "$COUNTER") + 1 ))
  echo "$next" > "$COUNTER"
  newbody=$(cat "$bodyfile")
  updated=$(jq -c --argjson id "$next" --arg body "$newbody" --argjson author_id "${WP_AUTHOR_ID:-9001}" --arg login "${WP_AUTHOR:-plan-bot}" '. + [{id:$id, body:$body, user:{id:$author_id, login:$login}}]' "$STORE")
  echo "$updated" > "$STORE"
  emit "$(jq -c --argjson id "$next" '.[] | select(.id == $id)' "$STORE")"
  exit 0
fi
if [[ "$method" == "PATCH" && "$endpoint" == *"/issues/comments/"* ]]; then
  cid="${endpoint##*/issues/comments/}"
  newbody=$(cat "$bodyfile")
  updated=$(jq -c --argjson id "$cid" --arg body "$newbody" 'map(if .id == $id then .body = $body else . end)' "$STORE")
  echo "$updated" > "$STORE"
  emit "$(jq -c --argjson id "$cid" '.[] | select(.id == $id)' "$STORE")"
  exit 0
fi
echo "fake-gh: unhandled $method $endpoint" >&2
exit 1
WPGH
chmod +x "$wp_root/bin/gh"

WP_WRITE="$SCRIPT_DIR/dispatch-write-plan"
WP_READ="$SCRIPT_DIR/dispatch-read-plan"

# Pin the trusted plan-comment author id for this block. Every positive test POSTs
# via dispatch-write-plan, whose POST the fake gh stamps with id ${WP_AUTHOR_ID:-9001};
# pinning DISPATCH_PLAN_AUTHOR_ID to the same id keeps the author-filtered scans
# matching, and short-circuits the scripts' `$(gh api user …)` default (the fake
# gh has no user endpoint).
export DISPATCH_PLAN_AUTHOR_ID=9001

# 1. write-creates: empty store → one comment containing the marker + PLAN A.
if ! PATH="$wp_root/bin:$SAVED_PATH" "$WP_WRITE" 7 <<<"PLAN A"; then
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan (test 1) failed unexpectedly"
fi
assert_eq "write-plan: store has exactly one comment after first write" \
  "1" "$(jq 'length' "$WP_STORE")"
TOTAL=$((TOTAL + 1))
if jq -e '.[0].body | contains("<!-- dispatch:plan -->") and contains("PLAN A")' "$WP_STORE" >/dev/null; then
  PASS=$((PASS + 1)); echo "  PASS: first comment carries the marker and PLAN A"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: first comment carries the marker and PLAN A"
fi

# 2. round-trip read returns the full (multi-line) body untruncated.
if ! PATH="$wp_root/bin:$SAVED_PATH" "$WP_WRITE" 7 <<<"$(printf 'PLAN A\nline two\nline three')"; then
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan (test 2) failed unexpectedly"
fi
read_out=""
read_out=$(PATH="$wp_root/bin:$SAVED_PATH" "$WP_READ" 7) || { FAIL=$((FAIL + 1)); echo "  FAIL: read-plan (test 2) exited non-zero unexpectedly"; }
TOTAL=$((TOTAL + 1))
if [[ "$read_out" == *"<!-- dispatch:plan -->"* && "$read_out" == *"line three"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan returns the full multi-line body with marker"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan returns the full multi-line body with marker"
  echo "    actual: '$read_out'"
fi

# 3. write-updates-in-place: still exactly one comment; read now returns PLAN B.
if ! PATH="$wp_root/bin:$SAVED_PATH" "$WP_WRITE" 7 <<<"PLAN B"; then
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan (test 3) failed unexpectedly"
fi
assert_eq "write-plan: still exactly one comment after update" \
  "1" "$(jq 'length' "$WP_STORE")"
read_out=""
read_out=$(PATH="$wp_root/bin:$SAVED_PATH" "$WP_READ" 7) || { FAIL=$((FAIL + 1)); echo "  FAIL: read-plan (test 3) exited non-zero unexpectedly"; }
TOTAL=$((TOTAL + 1))
if [[ "$read_out" == *"PLAN B"* && "$read_out" != *"PLAN A"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan returns updated PLAN B, not PLAN A"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan returns updated PLAN B, not PLAN A"
  echo "    actual: '$read_out'"
fi

# 4. read-missing-errors: fresh empty store, unknown issue → exit 1 + diagnostic.
wp_empty=$(mktemp -d); mkdir -p "$wp_empty/bin"
# Reuse the same fake gh but point it at a fresh empty store.
sed "s|$WP_STORE|$wp_empty/store.json|; s|$WP_COUNTER|$wp_empty/counter|" \
  "$wp_root/bin/gh" > "$wp_empty/bin/gh"
chmod +x "$wp_empty/bin/gh"
echo '[]' > "$wp_empty/store.json"; echo '0' > "$wp_empty/counter"
if read_err=$(PATH="$wp_empty/bin:$SAVED_PATH" "$WP_READ" 99 2>&1 1>/dev/null); then rc=0; else rc=$?; fi
assert_eq "read-plan: missing comment exits non-zero" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$read_err" == *"dispatch:plan"* || "$read_err" == *"no "*"comment"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan emits a clear missing-comment diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan emits a clear missing-comment diagnostic"
  echo "    actual: '$read_err'"
fi
rm -rf "$wp_empty"

# 6. reclaimed-login injection: a marker comment that reuses the trusted login but
#    carries a DIFFERENT numeric id (the renamed-and-reclaimed-login attack) must be
#    ignored by read-plan, and write-plan must NOT adopt (PATCH) it — it POSTs a
#    fresh trusted-authored comment instead. Guards the #1644 id-gate over the #1222
#    login-gate: a login-only filter would accept this forgery; the .user.id filter
#    rejects it. Without any author filter, read-plan would execute the forged plan
#    and write-plan would clobber the attacker's comment with the real plan.
wp_forge=$(mktemp -d); mkdir -p "$wp_forge/bin"
sed "s|$WP_STORE|$wp_forge/store.json|; s|$WP_COUNTER|$wp_forge/counter|" \
  "$wp_root/bin/gh" > "$wp_forge/bin/gh"
chmod +x "$wp_forge/bin/gh"
# Seed one attacker comment carrying the marker, reusing the trusted login but with
# a different numeric id (6666 ≠ trusted 9001) — the reclaimed-login forgery; counter=1
# so the next POST gets id 2 (no id collision with the seeded comment id 1).
echo '1' > "$wp_forge/counter"
jq -nc '[{id:1, body:"<!-- dispatch:plan -->\nFORGED PLAN", user:{id:6666, login:"plan-bot"}}]' > "$wp_forge/store.json"

# 6a. read-plan ignores the forged comment → exit 1 + missing-comment diagnostic.
if read_err=$(PATH="$wp_forge/bin:$SAVED_PATH" "$WP_READ" 7 2>&1 1>/dev/null); then rc=0; else rc=$?; fi
assert_eq "read-plan: foreign-authored marker comment is ignored (exit 1)" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$read_err" == *"dispatch:plan"* || "$read_err" == *"no "*"comment"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan ignores a forged foreign-authored plan comment"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan ignores a forged foreign-authored plan comment"
  echo "    actual: '$read_err'"
fi

# 6b. write-plan POSTs a fresh trusted comment rather than PATCHing the attacker's.
if ! PATH="$wp_forge/bin:$SAVED_PATH" "$WP_WRITE" 7 <<<"REAL PLAN"; then
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan (foreign-author) failed unexpectedly"
fi
assert_eq "write-plan: foreign-author store has two comments (attacker + new trusted)" \
  "2" "$(jq 'length' "$wp_forge/store.json")"
TOTAL=$((TOTAL + 1))
if jq -e '.[] | select(.id == 1) | .body == "<!-- dispatch:plan -->\nFORGED PLAN"' "$wp_forge/store.json" >/dev/null; then
  PASS=$((PASS + 1)); echo "  PASS: write-plan leaves the attacker comment body unchanged"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan leaves the attacker comment body unchanged"
fi
TOTAL=$((TOTAL + 1))
if jq -e '.[] | select(.user.id == 9001) | (.body | contains("<!-- dispatch:plan -->") and contains("REAL PLAN"))' "$wp_forge/store.json" >/dev/null; then
  PASS=$((PASS + 1)); echo "  PASS: write-plan POSTs a fresh trusted-authored plan comment"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan POSTs a fresh trusted-authored plan comment"
fi

# 6c. read-plan now returns the trusted plan, not the forged one.
read_out=""
read_out=$(PATH="$wp_forge/bin:$SAVED_PATH" "$WP_READ" 7) || { FAIL=$((FAIL + 1)); echo "  FAIL: read-plan (foreign-author) exited non-zero unexpectedly"; }
TOTAL=$((TOTAL + 1))
if [[ "$read_out" == *"REAL PLAN"* && "$read_out" != *"FORGED PLAN"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan returns the trusted plan, not the forged one"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan returns the trusted plan, not the forged one"
  echo "    actual: '$read_out'"
fi
rm -rf "$wp_forge"

# Build a bare-repo + worktree fixture whose origin remote is <url>. Creates a
# temp root with .bare/, seeds one commit on main via a throwaway seed repo,
# adds a worktree at worktrees/42-foo, and echoes the root path for the caller
# to capture. Serves both the real-github.com 5a case and the malformed-URL
# 5b-5e cases:
#   root=$(make_bare_worktree_fixture <url>)
make_bare_worktree_fixture() {
  set -e
  local url="$1"
  local root seed
  root=$(mktemp -d)
  git init --bare "$root/.bare" >/dev/null 2>&1
  git --git-dir="$root/.bare" config user.email "t@t" 2>/dev/null
  git --git-dir="$root/.bare" config user.name "t" 2>/dev/null
  git --git-dir="$root/.bare" remote add origin "$url"
  seed=$(mktemp -d)
  git -C "$seed" init -q
  git -C "$seed" config user.email "t@t"; git -C "$seed" config user.name "t"
  git -C "$seed" commit -q --allow-empty -m seed
  git -C "$seed" remote add bare "$root/.bare"
  git -C "$seed" push -q bare HEAD:refs/heads/main
  rm -rf "$seed"
  mkdir -p "$root/worktrees"
  git --git-dir="$root/.bare" worktree add -q "$root/worktrees/42-foo" main 2>/dev/null
  printf '%s' "$root"
}

# 5. bare+worktree repo resolution: from a worktree whose dirname(common_dir) is
# NOT a git repo (the real bare-repo + worktrees layout), with GH_REPO unset, both
# scripts must still resolve the repo for gh. This would FAIL against the pre-fix
# `cd "$(dirname "$common_dir")"` version, which lands in the non-repo container and
# leaves gh's {owner}/{repo} unresolvable (and GH_REPO unset). The fake gh below
# requires GH_REPO and never reads cwd, so it stands in for that failure.
bw_root=$(make_bare_worktree_fixture https://github.com/natb1/commons.systems.git)

# Fake gh that requires GH_REPO (never reads cwd) over a fresh JSON store.
mkdir -p "$bw_root/bin"
BW_STORE="$bw_root/store.json"; BW_COUNTER="$bw_root/counter"
echo '[]' > "$BW_STORE"; echo '0' > "$BW_COUNTER"
cat > "$bw_root/bin/gh" <<BWGH
#!/usr/bin/env bash
set -uo pipefail
if [[ -z "\${GH_REPO:-}" ]]; then
  echo "fatal: not a git repository (GH_REPO unset, no cwd repo)" >&2; exit 1
fi
STORE="$BW_STORE"; COUNTER="$BW_COUNTER"
BWGH
# Reuse the same emulator body as the main fake gh (everything from method="GET" onward).
sed -n '/^method="GET"/,$p' "$wp_root/bin/gh" >> "$bw_root/bin/gh"
chmod +x "$bw_root/bin/gh"
bash -n "$bw_root/bin/gh" || { FAIL=$((FAIL + 1)); echo "  FAIL: bare+worktree fake gh is not valid bash"; }

# write from the worktree, GH_REPO unset
if ( cd "$bw_root/worktrees/42-foo" && printf 'PLAN Z\n' | PATH="$bw_root/bin:$SAVED_PATH" env -u GH_REPO "$WP_WRITE" 42 ); then
  bw_write_rc=0; else bw_write_rc=$?; fi
assert_eq "write-plan: resolves repo in bare+worktree layout with GH_REPO unset (exit 0)" "0" "$bw_write_rc"

bw_read_out=$( cd "$bw_root/worktrees/42-foo" && PATH="$bw_root/bin:$SAVED_PATH" env -u GH_REPO "$WP_READ" 42 ) && bw_read_rc=0 || bw_read_rc=$?
assert_eq "read-plan: resolves repo in bare+worktree layout with GH_REPO unset (exit 0)" "0" "$bw_read_rc"
TOTAL=$((TOTAL + 1))
if [[ "$bw_read_out" == *"PLAN Z"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan round-trips the plan in the bare+worktree layout"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan round-trips the plan in the bare+worktree layout"
  echo "    actual: '$bw_read_out'"
fi
git --git-dir="$bw_root/.bare" worktree prune 2>/dev/null || true
rm -rf "$bw_root"

# 5b. malformed-URL format guard: SSH-with-port → read-plan rejects it.
# ssh://git@github.com:22/owner/repo.git strips to "22/owner/repo" — two slashes,
# would pass the old */* check but fails the strict ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ regex.
mf_ssh_root=$(make_bare_worktree_fixture ssh://git@github.com:22/owner/repo.git)
if err=$( cd "$mf_ssh_root/worktrees/42-foo" && env -u GH_REPO "$WP_READ" 42 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "read-plan: SSH-with-port malformed URL exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"unexpected owner/repo format"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan rejects SSH-with-port malformed URL with format-guard diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan rejects SSH-with-port malformed URL with format-guard diagnostic"
  echo "    actual: '$err'"
fi
git --git-dir="$mf_ssh_root/.bare" worktree prune 2>/dev/null || true
rm -rf "$mf_ssh_root"

# 5c. malformed-URL format guard: non-GitHub remote → write-plan rejects it.
# https://gitlab.com/owner/repo.git has no "github.com" to strip, so repo stays the
# full URL (contains ":") — has slashes, would pass the old */* check but fails the regex.
mf_gl_root=$(make_bare_worktree_fixture https://gitlab.com/owner/repo.git)
if err=$( cd "$mf_gl_root/worktrees/42-foo" && env -u GH_REPO "$WP_WRITE" 42 <<<"PLAN" 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "write-plan: non-GitHub remote malformed URL exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"remote is not a GitHub repository"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: write-plan rejects non-GitHub remote URL with not-GitHub diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan rejects non-GitHub remote URL with not-GitHub diagnostic"
  echo "    actual: '$err'"
fi
git --git-dir="$mf_gl_root/.bare" worktree prune 2>/dev/null || true
rm -rf "$mf_gl_root"

# 5d. malformed-URL format guard: SSH-with-port → write-plan rejects it.
# Symmetric counterpart to 5b: same ssh://git@github.com:22/owner/repo.git fixture,
# exercised against dispatch-write-plan instead of dispatch-read-plan.
mf_ssh_w_root=$(make_bare_worktree_fixture ssh://git@github.com:22/owner/repo.git)
if err=$( cd "$mf_ssh_w_root/worktrees/42-foo" && env -u GH_REPO "$WP_WRITE" 42 <<<"PLAN" 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "write-plan: SSH-with-port malformed URL exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"unexpected owner/repo format"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: write-plan rejects SSH-with-port malformed URL with format-guard diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan rejects SSH-with-port malformed URL with format-guard diagnostic"
  echo "    actual: '$err'"
fi
git --git-dir="$mf_ssh_w_root/.bare" worktree prune 2>/dev/null || true
rm -rf "$mf_ssh_w_root"

# 5e. malformed-URL format guard: non-GitHub remote → read-plan rejects it.
# Symmetric counterpart to 5c: same https://gitlab.com/owner/repo.git fixture,
# exercised against dispatch-read-plan instead of dispatch-write-plan.
mf_gl_r_root=$(make_bare_worktree_fixture https://gitlab.com/owner/repo.git)
if err=$( cd "$mf_gl_r_root/worktrees/42-foo" && env -u GH_REPO "$WP_READ" 42 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "read-plan: non-GitHub remote malformed URL exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"remote is not a GitHub repository"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan rejects non-GitHub remote URL with not-GitHub diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan rejects non-GitHub remote URL with not-GitHub diagnostic"
  echo "    actual: '$err'"
fi
git --git-dir="$mf_gl_r_root/.bare" worktree prune 2>/dev/null || true
rm -rf "$mf_gl_r_root"

# 7. two-matching-plan-comments: when the store contains two comments both
#    authored by plan-bot and both carrying the marker, read-plan must return
#    the FIRST one without a SIGPIPE-induced exit-141 failure, and write-plan
#    must PATCH that first comment (not POST a third) and also exit 0. Guards the
#    #1643 regression: the old `| head -n1` pipeline under `set -euo pipefail`
#    sent SIGPIPE (exit 141) to the upstream jq process when more than one
#    comment matched, causing a spurious non-zero exit with no diagnostic.
#    dispatch-write-plan received the identical `first()` fix at line 65, so a
#    parallel write sub-case below guards write-plan's copy independently.
wp_two=$(mktemp -d); mkdir -p "$wp_two/bin"
sed "s|$WP_STORE|$wp_two/store.json|; s|$WP_COUNTER|$wp_two/counter|" \
  "$wp_root/bin/gh" > "$wp_two/bin/gh"
chmod +x "$wp_two/bin/gh"
echo '0' > "$wp_two/counter"
# Seed two marker comments both authored by plan-bot; write directly (write-plan
# enforces the at-most-one invariant, so seeding two requires bypassing it).
MARKER='<!-- dispatch:plan -->'
jq -nc --arg m "$MARKER" \
  '[{id:1, body:($m + "\nFIRST PLAN"), user:{id:9001, login:"plan-bot"}},
    {id:2, body:($m + "\nSECOND PLAN"), user:{id:9001, login:"plan-bot"}}]' \
  > "$wp_two/store.json"
read_out=$(PATH="$wp_two/bin:$SAVED_PATH" "$WP_READ" 7) && rc=0 || rc=$?
assert_eq "read-plan: two matching plan comments exit 0 (no SIGPIPE under pipefail, #1643)" "0" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$read_out" == *"FIRST PLAN"* && "$read_out" == *"$MARKER"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: read-plan returns first matching comment with marker (two-comment store)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: read-plan returns first matching comment with marker (two-comment store)"
  echo "    actual: '$read_out'"
fi

# 7b. write-plan against the same two-matching-comment store: write-plan's own
#     `first()` scan (line 65) must exit 0 (no SIGPIPE under pipefail) and PATCH
#     the FIRST matching comment in place — store length stays 2 (no third POST)
#     and comment id 1's body is updated. The read sub-case above does NOT cover
#     write-plan's copy of the fix; this guards it independently (#1643).
if PATH="$wp_two/bin:$SAVED_PATH" "$WP_WRITE" 7 <<<"UPDATED PLAN"; then wp_two_rc=0; else wp_two_rc=$?; fi
assert_eq "write-plan: two matching plan comments exit 0 (no SIGPIPE under pipefail, #1643)" "0" "$wp_two_rc"
assert_eq "write-plan: two matching plan comments → PATCH first, no third POST (store length 2)" \
  "2" "$(jq 'length' "$wp_two/store.json")"
TOTAL=$((TOTAL + 1))
if jq -e --arg m "$MARKER" '.[] | select(.id == 1) | (.body | contains($m) and contains("UPDATED PLAN"))' "$wp_two/store.json" >/dev/null; then
  PASS=$((PASS + 1)); echo "  PASS: write-plan PATCHes the first matching comment (id 1 body updated)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: write-plan PATCHes the first matching comment (id 1 body updated)"
  echo "    actual: '$(jq -c '.[] | select(.id == 1) | .body' "$wp_two/store.json")'"
fi
rm -rf "$wp_two"

rm -rf "$wp_root"
unset DISPATCH_PLAN_AUTHOR_ID

echo ""
echo "=== gh_repo_from_remote ==="

# gh_repo_from_remote is pure string logic (no git, no gh), so each case sources
# the real lib.sh in a subshell and calls the helper directly. Success cases
# assert the derived owner/repo; failure cases assert a non-zero return and that
# the caller-name prefix appears in the stderr diagnostic (AC: error messages
# include the caller name).

# Success — HTTPS with .git suffix.
if out=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "https://github.com/natb1/commons.systems.git" probe 2>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "gh_repo_from_remote: https .git → owner/repo" "natb1/commons.systems" "$out"
assert_eq "gh_repo_from_remote: https .git → exit 0" "0" "$rc"

# Success — HTTPS without .git suffix.
out=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "https://github.com/natb1/commons.systems" probe 2>/dev/null )
assert_eq "gh_repo_from_remote: https no-.git → owner/repo" "natb1/commons.systems" "$out"

# Success — SSH scp-style.
out=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "git@github.com:natb1/commons.systems.git" probe 2>/dev/null )
assert_eq "gh_repo_from_remote: ssh → owner/repo" "natb1/commons.systems" "$out"

# Failure — empty URL: non-zero return, caller-prefixed "could not resolve" diagnostic.
if err=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "" probe 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "gh_repo_from_remote: empty URL exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"probe: could not resolve owner/repo"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: gh_repo_from_remote empty URL emits caller-prefixed diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: gh_repo_from_remote empty URL emits caller-prefixed diagnostic"
  echo "    actual: '$err'"
fi

# Failure — non-GitHub remote: non-zero return, caller-prefixed not-GitHub diagnostic.
if err=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "https://gitlab.com/a/b" probe 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "gh_repo_from_remote: non-GitHub remote exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"probe: remote is not a GitHub repository"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: gh_repo_from_remote non-GitHub remote emits caller-prefixed diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: gh_repo_from_remote non-GitHub remote emits caller-prefixed diagnostic"
  echo "    actual: '$err'"
fi

# Failure — malformed owner/repo (no slash): non-zero return, format diagnostic.
if err=$( source "$SCRIPT_DIR/lib.sh"; gh_repo_from_remote "https://github.com/onlyowner" probe 2>&1 1>/dev/null ); then rc=0; else rc=$?; fi
assert_eq "gh_repo_from_remote: malformed owner/repo exits 1" "1" "$rc"
TOTAL=$((TOTAL + 1))
if [[ "$err" == *"probe: unexpected owner/repo format"* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: gh_repo_from_remote malformed owner/repo emits caller-prefixed diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: gh_repo_from_remote malformed owner/repo emits caller-prefixed diagnostic"
  echo "    actual: '$err'"
fi

# ============================================================================
# claim_fixed_vite_port (fixed Vite-port pool) tests
# ============================================================================
echo ""
echo "=== claim_fixed_vite_port (fixed Vite-port pool) ==="

# Isolation: every sub-test sources lib.sh in a subshell, then overrides
# QA_VITE_PORT_LOCK_DIR (fresh mktemp -d) and QA_VITE_PORT_POOL (a known-free
# 8-port set discovered via find_available_ports) so the suite never touches a
# real QA server on 5170–5177 and needs no privileges. The pool/lock-dir are
# file-scope globals in lib.sh precisely so the overrides take after sourcing.
cvp_pool=$(source "$SCRIPT_DIR/lib.sh"; find_available_ports 8)
read -r -a CVP_POOL_ARR <<< "$cvp_pool"
assert_eq "claim: discovered an 8-member known-free test pool" "8" "${#CVP_POOL_ARR[@]}"

# --- Case 1: single claim returns a pool member -----------------------------
cvp_lockdir1=$(mktemp -d)
cvp_out1=$(
  source "$SCRIPT_DIR/lib.sh"
  QA_VITE_PORT_LOCK_DIR="$cvp_lockdir1"
  QA_VITE_PORT_POOL=("${CVP_POOL_ARR[@]}")
  claim_fixed_vite_port && echo "$VITE_PORT"
) && cvp_rc1=0 || cvp_rc1=$?
assert_eq "claim: single claim succeeds (exit 0)" "0" "$cvp_rc1"
TOTAL=$((TOTAL + 1))
if [[ " ${CVP_POOL_ARR[*]} " == *" $cvp_out1 "* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: single claim's VITE_PORT ($cvp_out1) is a pool member"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: single claim's VITE_PORT ('$cvp_out1') is not a pool member"
fi
rm -rf "$cvp_lockdir1"

# --- Case 2: 8 concurrent claims yield 8 distinct ports ---------------------
# Each worker claims, records its port, then sleeps to HOLD its flock while the
# siblings race — without the hold a fast worker could release and a slow one
# reuse the same slot, masking a collision.
cvp_lockdir2=$(mktemp -d)
cvp_results2=$(mktemp -d)
for i in $(seq 1 8); do
  (
    source "$SCRIPT_DIR/lib.sh"
    QA_VITE_PORT_LOCK_DIR="$cvp_lockdir2"
    QA_VITE_PORT_POOL=("${CVP_POOL_ARR[@]}")
    if claim_fixed_vite_port; then
      echo "$VITE_PORT" > "$cvp_results2/$i"
      sleep 3
    fi
  ) &
done
wait
cvp_total2=$(find "$cvp_results2" -type f | wc -l | tr -d ' ')
cvp_distinct2=$(find "$cvp_results2" -type f -exec cat {} + 2>/dev/null | sort -un | sed '/^$/d' | wc -l | tr -d ' ')
assert_eq "claim: 8 concurrent claims all succeed" "8" "$cvp_total2"
assert_eq "claim: 8 concurrent claims yield 8 distinct ports" "8" "$cvp_distinct2"
rm -rf "$cvp_lockdir2" "$cvp_results2"

# --- Case 3: 9th claim errors, no random-port fallback ----------------------
# Hold all 8 slots with background workers, then a 9th claim must exit non-zero,
# print the "all … in use" diagnostic, and leave VITE_PORT unset (no fallback).
cvp_lockdir3=$(mktemp -d)
cvp_results3=$(mktemp -d)
for i in $(seq 1 8); do
  (
    source "$SCRIPT_DIR/lib.sh"
    QA_VITE_PORT_LOCK_DIR="$cvp_lockdir3"
    QA_VITE_PORT_POOL=("${CVP_POOL_ARR[@]}")
    if claim_fixed_vite_port; then
      echo "$VITE_PORT" > "$cvp_results3/$i"
      sleep 4
    fi
  ) &
done
# Wait until all 8 holders have actually claimed before racing the 9th.
for _ in $(seq 1 80); do
  [ "$(find "$cvp_results3" -type f | wc -l | tr -d ' ')" -eq 8 ] && break
  sleep 0.1
done
cvp_stderr3=$(mktemp)
cvp_9th_out=$(
  source "$SCRIPT_DIR/lib.sh"
  QA_VITE_PORT_LOCK_DIR="$cvp_lockdir3"
  QA_VITE_PORT_POOL=("${CVP_POOL_ARR[@]}")
  unset VITE_PORT
  if claim_fixed_vite_port 2>"$cvp_stderr3"; then
    echo "0 ${VITE_PORT:-UNSET}"
  else
    echo "1 ${VITE_PORT:-UNSET}"
  fi
)
wait
cvp_9th_rc="${cvp_9th_out%% *}"
cvp_9th_port="${cvp_9th_out#* }"
assert_eq "claim: 9th claim (all slots held) exits non-zero" "1" "$cvp_9th_rc"
assert_eq "claim: 9th claim leaves VITE_PORT unset (no random-port fallback)" "UNSET" "$cvp_9th_port"
TOTAL=$((TOTAL + 1))
if grep -q "all .* QA Vite ports .* are in use" "$cvp_stderr3"; then
  PASS=$((PASS + 1)); echo "  PASS: 9th claim prints the 'all … in use' diagnostic"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: 9th claim did not print the expected diagnostic"
  echo "    stderr: '$(cat "$cvp_stderr3")'"
fi
rm -rf "$cvp_lockdir3" "$cvp_results3" "$cvp_stderr3"

# --- Case 4: a foreign squatter on a pool port is skipped -------------------
# Bind the first pool port with a foreign listener; a claim must win the NEXT
# free slot (post-lock bindability check), not die on the squatted port.
cvp_lockdir4=$(mktemp -d)
cvp_squat_port="${CVP_POOL_ARR[0]}"
# The squatter retries on error (so a transient collision can't kill it) and
# announces readiness by printing READY once bound. We wait for that line rather
# than bind-probing the port ourselves — a probe would momentarily hold the port
# and race the squatter's own listen, which is exactly the flake to avoid.
cvp_squat_out=$(mktemp)
node -e "const net=require('net');function bind(){const s=net.createServer();s.on('error',()=>setTimeout(bind,50));s.listen(${cvp_squat_port},'0.0.0.0',()=>console.log('READY'));}bind();setInterval(()=>{},1e9);" >"$cvp_squat_out" 2>/dev/null &
cvp_squat_pid=$!
# Wait until the squatter reports it has bound the port.
for _ in $(seq 1 100); do
  grep -q READY "$cvp_squat_out" 2>/dev/null && break
  sleep 0.1
done
cvp_out4=$(
  source "$SCRIPT_DIR/lib.sh"
  QA_VITE_PORT_LOCK_DIR="$cvp_lockdir4"
  QA_VITE_PORT_POOL=("${CVP_POOL_ARR[@]}")
  claim_fixed_vite_port && echo "$VITE_PORT"
) && cvp_rc4=0 || cvp_rc4=$?
assert_eq "claim: squatted pool port → claim succeeds on next slot (exit 0)" "0" "$cvp_rc4"
TOTAL=$((TOTAL + 1))
if [[ "$cvp_out4" != "$cvp_squat_port" && " ${CVP_POOL_ARR[*]} " == *" $cvp_out4 "* ]]; then
  PASS=$((PASS + 1)); echo "  PASS: claim skipped the squatted port ($cvp_squat_port), took $cvp_out4"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: claim returned '$cvp_out4' (squatted port was $cvp_squat_port)"
fi
kill "$cvp_squat_pid" 2>/dev/null || true
wait "$cvp_squat_pid" 2>/dev/null || true
rm -rf "$cvp_lockdir4" "$cvp_squat_out"

# ============================================================================
# dispatch-reconcile-ready tests
# ============================================================================
echo ""
echo "=== dispatch-reconcile-ready ==="

# Build a single-PR fixture array for the reconcile fetch. Shapes match the
# `gh pr list --json number,isDraft,labels,headRefOid,mergeable` output the
# script consumes; the CI verdict now derives from the REST check-runs of
# headRefOid (#1601), so also write the matching check-runs fixture.
#   $1 = number, $2 = isDraft (true|false), $3 = mergeable
#   (MERGEABLE|CONFLICTING|UNKNOWN), $4 = rollup JSON, $5 = labels JSON.
make_reconcile_pr() {
  local num="$1" is_draft="$2" mergeable="$3" rollup_json="$4" labels_json="$5"
  local sha="sha${num}"
  write_rest_check_runs "$sha" "$rollup_json"
  printf '[{"number":%s,"isDraft":%s,"mergeable":"%s","headRefOid":"%s","labels":%s}]' \
    "$num" "$is_draft" "$mergeable" "$sha" "$labels_json"
}

# Labels: a single dispatch:reviewed label, and the no-reviewed scope case.
REVIEWED_LABELS='[{"name":"dispatch:reviewed"}]'
NO_REVIEWED_LABELS='[{"name":"dispatch:planned"}]'

# Reports whether a given stub log file is present/absent.
reconcile_log_state() {
  [[ -f "$STUB_DIR/$1" ]] && echo "present" || echo "absent"
}

# --- Truth table for a dispatch:reviewed PR ---------------------------------
# Each row writes a one-PR fixture, runs the reconciler, and asserts on the
# emitted stdout plus the promote/demote call logs.

# Row 1: draft + passing + MERGEABLE → promote.
echo "Test: draft + passing + MERGEABLE → promote (#7)"
setup
make_reconcile_pr 7 true MERGEABLE "$GREEN_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "promote: stdout is 'promoted #7'" "promoted #7" "$out"
assert_eq "promote: gh pr ready #7 logged" "7" "$(cat "$STUB_DIR/gh-pr-ready.log")"
assert_eq "promote: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# Row 2: draft + passing + UNKNOWN → no-op (mergeable async, self-heal later).
echo "Test: draft + passing + UNKNOWN → no-op (#8)"
setup
make_reconcile_pr 8 true UNKNOWN "$GREEN_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "draft+UNKNOWN: no stdout" "" "$out"
assert_eq "draft+UNKNOWN: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
assert_eq "draft+UNKNOWN: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# Row 3: draft + failing + MERGEABLE → no-op (a draft is never demoted).
echo "Test: draft + failing + MERGEABLE → no-op (#9)"
setup
make_reconcile_pr 9 true MERGEABLE "$FAILING_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "draft+failing: no stdout" "" "$out"
assert_eq "draft+failing: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
assert_eq "draft+failing: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# Row 4: draft + pending + MERGEABLE → no-op (CI still running).
echo "Test: draft + pending + MERGEABLE → no-op (#10)"
setup
make_reconcile_pr 10 true MERGEABLE "$PENDING_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "draft+pending: no stdout" "" "$out"
assert_eq "draft+pending: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
teardown

# Row 5: ready + failing + MERGEABLE → demote (CI regressed).
echo "Test: ready + failing + MERGEABLE → demote (#11)"
setup
make_reconcile_pr 11 false MERGEABLE "$FAILING_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "demote (failing): stdout reports verdict + mergeable" \
  "demoted #11 (ci=failing merge=MERGEABLE)" "$out"
assert_eq "demote (failing): gh pr ready --undo #11 logged" \
  "11" "$(cat "$STUB_DIR/gh-pr-ready-undo.log")"
assert_eq "demote (failing): no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
# dispatch:reviewed is KEPT — no remove-label of it.
assert_eq "demote (failing): dispatch:reviewed not removed" \
  "absent" "$(reconcile_log_state gh-pr-edit.log)"
teardown

# Row 6: ready + passing + CONFLICTING → demote (merge conflict).
echo "Test: ready + passing + CONFLICTING → demote (#12)"
setup
make_reconcile_pr 12 false CONFLICTING "$GREEN_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "demote (CONFLICTING): stdout reports verdict + mergeable" \
  "demoted #12 (ci=passing merge=CONFLICTING)" "$out"
assert_eq "demote (CONFLICTING): gh pr ready --undo #12 logged" \
  "12" "$(cat "$STUB_DIR/gh-pr-ready-undo.log")"
teardown

# Row 7: ready + passing + UNKNOWN → no-op (do NOT demote on UNKNOWN).
echo "Test: ready + passing + UNKNOWN → no-op (#13)"
setup
make_reconcile_pr 13 false UNKNOWN "$GREEN_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "ready+UNKNOWN: no stdout" "" "$out"
assert_eq "ready+UNKNOWN: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# Row 8: ready + pending + MERGEABLE → no-op (do NOT demote on pending CI).
echo "Test: ready + pending + MERGEABLE → no-op (#14)"
setup
make_reconcile_pr 14 false MERGEABLE "$PENDING_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "ready+pending: no stdout" "" "$out"
assert_eq "ready+pending: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# Row 9: ready + passing + MERGEABLE → no-op (already correct).
echo "Test: ready + passing + MERGEABLE → no-op (already correct) (#15)"
setup
make_reconcile_pr 15 false MERGEABLE "$GREEN_ROLLUP" "$REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "ready+correct: no stdout" "" "$out"
assert_eq "ready+correct: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
assert_eq "ready+correct: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# --- Scope gate: a PR WITHOUT dispatch:reviewed is never flipped -------------
# Use the would-promote combination (draft + passing + MERGEABLE): the only
# thing withholding the flip is the missing label.
echo "Test: scope gate — no dispatch:reviewed → never flipped, even when promotable (#16)"
setup
make_reconcile_pr 16 true MERGEABLE "$GREEN_ROLLUP" "$NO_REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "scope gate: no stdout" "" "$out"
assert_eq "scope gate: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
assert_eq "scope gate: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
assert_eq "scope gate: no remove-label call" "absent" "$(reconcile_log_state gh-issue-remove-label-rest-calls.log)"
teardown

# Scope gate, ready side: a non-reviewed ready PR that is failing+CONFLICTING
# (the strongest demote signal) is still never demoted.
echo "Test: scope gate — no dispatch:reviewed ready+failing+CONFLICTING → never demoted (#17)"
setup
make_reconcile_pr 17 false CONFLICTING "$FAILING_ROLLUP" "$NO_REVIEWED_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "scope gate (ready): no stdout" "" "$out"
assert_eq "scope gate (ready): no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# --- Attempt-clear: promote removes ALL dispatch:*-attempt-* labels ---------
# A promotable PR also carries two attempt counters; both are removed via
# gh_issue_remove_label_rest (REST DELETE .../issues/<N>/labels/<name>; PRs are
# issues in REST), and dispatch:reviewed is NOT among the removed.
echo "Test: promote clears all dispatch:*-attempt-* labels, keeps dispatch:reviewed (#18)"
setup
ATTEMPT_LABELS='[{"name":"dispatch:reviewed"},{"name":"dispatch:verify-attempt-2"},{"name":"dispatch:ci-wait-attempt-1"}]'
make_reconcile_pr 18 true MERGEABLE "$GREEN_ROLLUP" "$ATTEMPT_LABELS" \
  > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "attempt-clear: still promoted" "promoted #18" "$out"
assert_eq "attempt-clear: gh pr ready #18 logged" "18" "$(cat "$STUB_DIR/gh-pr-ready.log")"
rm_log=$(cat "$STUB_DIR/gh-issue-remove-label-rest-calls.log" 2>/dev/null || true)
TOTAL=$((TOTAL + 1))
if grep -q 'DELETE repos/{owner}/{repo}/issues/18/labels/dispatch:verify-attempt-2' <<<"$rm_log" \
   && grep -q 'DELETE repos/{owner}/{repo}/issues/18/labels/dispatch:ci-wait-attempt-1' <<<"$rm_log"; then
  PASS=$((PASS + 1)); echo "  PASS: attempt-clear: both attempt labels removed via REST DELETE"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: attempt-clear: both attempt labels removed via REST DELETE"
  echo "    actual gh-issue-remove-label-rest-calls.log: '$rm_log'"
fi
TOTAL=$((TOTAL + 1))
if grep -q 'labels/dispatch:reviewed' <<<"$rm_log"; then
  FAIL=$((FAIL + 1)); echo "  FAIL: attempt-clear: dispatch:reviewed must NOT be removed"
  echo "    actual gh-issue-remove-label-rest-calls.log: '$rm_log'"
else
  PASS=$((PASS + 1)); echo "  PASS: attempt-clear: dispatch:reviewed not removed"
fi
teardown

# --- Multi-PR: scope, promote, demote, and no-op coexist in one fetch --------
# A single fetch carrying four PRs reconciles each independently: a reviewed
# promotable PR is promoted, a reviewed demotable PR is demoted, a non-reviewed
# promotable PR is skipped, and a reviewed already-correct PR is a no-op.
echo "Test: multi-PR fetch reconciles each PR independently"
setup
# Each PR's CI verdict derives from the REST check-runs of its headRefOid (#1601);
# all four are green here.
for n in 20 21 22 23; do
  printf '%s' "{\"check_runs\": $GREEN_ROLLUP}" > "$STUB_DIR/check-runs-sha${n}.json"
done
{
  printf '[\n'
  printf '{"number":20,"isDraft":true,"mergeable":"MERGEABLE","headRefOid":"sha20","labels":%s},\n' \
    "$REVIEWED_LABELS"
  printf '{"number":21,"isDraft":false,"mergeable":"CONFLICTING","headRefOid":"sha21","labels":%s},\n' \
    "$REVIEWED_LABELS"
  printf '{"number":22,"isDraft":true,"mergeable":"MERGEABLE","headRefOid":"sha22","labels":%s},\n' \
    "$NO_REVIEWED_LABELS"
  printf '{"number":23,"isDraft":false,"mergeable":"MERGEABLE","headRefOid":"sha23","labels":%s}\n' \
    "$REVIEWED_LABELS"
  printf ']\n'
} > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "multi: #20 promoted" "20" "$(cat "$STUB_DIR/gh-pr-ready.log")"
assert_eq "multi: #21 demoted" "21" "$(cat "$STUB_DIR/gh-pr-ready-undo.log")"
TOTAL=$((TOTAL + 1))
if grep -q 'promoted #20' <<<"$out" \
   && grep -q 'demoted #21 (ci=passing merge=CONFLICTING)' <<<"$out" \
   && ! grep -qE '#22|#23' <<<"$out"; then
  PASS=$((PASS + 1)); echo "  PASS: multi: stdout has promote+demote lines only for the two reviewed actionable PRs"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: multi: stdout has promote+demote lines only for the two reviewed actionable PRs"
  echo "    actual stdout: '$out'"
fi
teardown

# --- Empty fetch: no PRs → no output, no calls ------------------------------
echo "Test: no open PRs → no output, no calls"
setup
echo "[]" > "$STUB_DIR/reconcile-pr-list.json"
out=$("$TMPDIR_TEST/dispatch-reconcile-ready" 2>/dev/null)
assert_eq "empty fetch: no stdout" "" "$out"
assert_eq "empty fetch: no promote call" "absent" "$(reconcile_log_state gh-pr-ready.log)"
assert_eq "empty fetch: no demote call" "absent" "$(reconcile_log_state gh-pr-ready-undo.log)"
teardown

# --- Executable-bit guard ----------------------------------------------------
echo "Test: dispatch-reconcile-ready is executable"
assert_eq "dispatch-reconcile-ready is executable" "yes" \
