assert_eq "launch INVOKE /fix-conflicts: spawn-job argv (with model)" \
  "--no-verify --park-issue 839 --name $LW_WT_BASENAME --cwd $LW_WT --model claude-sonnet-4-6 /fix-conflicts 839 $LW_WT" "$sj"
