# 2. INVOKE /qa-fix → spawn-job carries --model claude-sonnet-4-6 (real
# dispatch-phase-model qa policy) and the /qa-fix prompt.
echo "Test: INVOKE /qa-fix → spawn-job with --model claude-sonnet-4-6"
lw_setup
lw_write_marker
