printf '[%s]' "$(make_auto_merge_pr 50 false MERGEABLE "$GREEN_ROLLUP" "$AM_REVIEWED" '[{"number":100},{"number":101}]')" \
  > "$STUB_DIR/auto-merge-pr-list.json"
